  { agent: "risk", text: "drawdown inside envelope. go.", tone: "amber" },
  { agent: "crawler", text: "holder #688 just walked into the room.", tone: "amber" },
  { agent: "chief", text: "desk is open. keep the tape warm.", tone: "pink" },
  { agent: "crawler", text: "sandwich bot spotted. not our sandwich.", tone: "red" },
];

const INITIAL_ACTIVITY: ActivityItem[] = [
  { id: 4, agent: "chief", text: ACTIVITY_POOL[0].text, tone: "pink", time: "03:01 UTC" },
  { id: 3, agent: "crawler", text: ACTIVITY_POOL[7].text, tone: "amber", time: "03:01 UTC" },
  { id: 2, agent: "risk", text: ACTIVITY_POOL[6].text, tone: "amber", time: "03:00 UTC" },
];

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

export const fmtUsd = (value: number, digits = 0): string =>
  `$${value.toLocaleString("en-US", {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  })}`;

export const compact = (value: number): string => {
  if (Math.abs(value) >= 1_000_000) return `${(value / 1_000_000).toFixed(2)}M`;
  if (Math.abs(value) >= 1_000) return `${(value / 1_000).toFixed(1)}k`;
  return value.toFixed(0);
};

export const fmtPrice = (value: number): string => `$${value.toFixed(5)}`;

export const signed = (value: number, digits = 1): string =>
  `${value >= 0 ? "+" : "-"}${Math.abs(value).toFixed(digits)}`;

const pad2 = (value: number): string => String(value).padStart(2, "0");

function sessionLabel(seconds: number): string {
  const normalized = ((seconds % 86400) + 86400) % 86400;
  return `${pad2(Math.floor(normalized / 3600))}:${pad2(Math.floor((normalized % 3600) / 60))} UTC`;
}

function wave(seed: number, n: number, base: number, gain: number): number[] {
  return Array.from({ length: n }, (_, i) =>
    base + gain * (0.55 * Math.sin((seed + i) * 0.53) + 0.45 * Math.cos((seed + i) * 0.21)),
  );
}

export class MarketEngine {
  private rng: () => number;
  private readonly tickMs: number;
  private readonly startBalance: number;
  private seq = 0;
  private price = DOPE_START;
  private startPrice = DOPE_START;
  private balance: number;
  private peakBalance: number;
  private holders = 683;
  private scanned = 248;
  private fills = 1007;
  private volume24h = 2_170_000;
  private latency = 42;
  private gas = 0.031;
  private activeAgent: AgentId = "chief";
  private priceSeries: number[] = [];
  private equitySeries: number[] = [];
  private candles: Candle[] = [];
  private activity: ActivityItem[] = [];
  private thresholds: ThresholdRow[] = [];
  private book: BookSnapshot = { bid: DOPE_START * 0.998, ask: DOPE_START * 1.002, spreadPct: 0.4, depth: [] };
  latest: DashboardSnapshot;

  constructor(options: EngineOptions = {}) {
    this.rng = mulberry32(options.seed ?? 0x5eed1e);
    this.tickMs = options.tickMs ?? 1800;
    this.startBalance = options.startBalance ?? 68_400;
    this.balance = this.startBalance;
    this.peakBalance = this.balance;
    for (let i = 0; i < 84; i += 1) this.step(false);
    this.seq = 0;
    this.activity = INITIAL_ACTIVITY;
    this.thresholds = this.buildThresholds();
    this.latest = this.buildSnapshot();
  }

  tick(): DashboardSnapshot {
    this.step(true);
    this.latest = this.buildSnapshot();
    return this.latest;
  }

  private step(recordActivity: boolean): void {
    const rng = this.rng;
    this.seq += 1;

    const shock = rng() < 0.07 ? (rng() - 0.58) * 0.038 : 0;
    const reversion = (DOPE_START - this.price) / DOPE_START * 0.018;
    const open = this.price;
    const close = clamp(open * (1 + reversion + 0.001 + (rng() - 0.485) * 0.012 + shock), 0.0009, 0.02);
    const high = Math.max(open, close) * (1 + rng() * 0.0034);
    const low = Math.min(open, close) * (1 - rng() * 0.0034);
    const volume = 68_000 + rng() * 212_000 + Math.abs(close - open) / open * 7_000_000;
    this.price = close;
    this.candles = [...this.candles, { t: this.seq, open, close, high, low, volume }].slice(-MAX_CANDLES);
    this.priceSeries = [...this.priceSeries, close].slice(-MAX_PRICE_POINTS);

    const equityDelta = (TARGET_BALANCE - this.balance) * 0.006 + (rng() - 0.42) * 390;
    this.balance = Math.max(50_000, this.balance + equityDelta);
    this.peakBalance = Math.max(this.peakBalance, this.balance);
    this.equitySeries = [...this.equitySeries, this.balance].slice(-MAX_EQUITY_POINTS);

    this.volume24h += volume * 0.22;
    this.fills += Math.round(rng() * 9);
    this.holders = Math.round(clamp(this.holders + (rng() - 0.32) * 14, 420, 5000));
    this.scanned = Math.round(clamp(this.scanned + rng() * 8, 0, 99_999));
    this.latency = 32 + Math.round(rng() * 38);
    this.gas = 0.018 + rng() * 0.024;

    const spread = this.price * (0.002 + rng() * 0.0016);
    this.book = {
      bid: this.price - spread / 2,
      ask: this.price + spread / 2,
      spreadPct: (spread / this.price) * 100,
      depth: Array.from({ length: 12 }, () => 0.2 + rng() * 0.8),
    };

    const poolIndex = Math.floor(rng() * ACTIVITY_POOL.length);
    const nextAgent = AGENT_IDS[Math.floor(rng() * AGENT_IDS.length)];
    if (recordActivity) {
      const line = ACTIVITY_POOL[poolIndex];
      this.activeAgent = line.agent;
      const next: ActivityItem = {
        id: this.seq,
        agent: line.agent,
        text: line.text,
        tone: line.tone,
        time: this.timeFor(-1),
      };
      this.activity = [next, ...this.activity].slice(0, 6);
    } else {
      this.activeAgent = nextAgent;
    }
    this.thresholds = this.buildThresholds();
  }

  private timeFor(offsetTicks: number): string {
    return sessionLabel(SESSION_START_SEC + (this.seq + offsetTicks) * 7);
  }

  private buildThresholds(): ThresholdRow[] {
    const wobble = (Math.sin(this.seq * 0.7) + 1) / 2;
    return [
      { label: "MIN_AGE_SEC", value: "88", hint: "24h", tone: "mint" },
      { label: "MIN_LIQUIDITY_USD", value: `${(12 + wobble * 0.6).toFixed(1)}k`, hint: "1,240", tone: "mint" },
      { label: "MIN_VOLUME_24H", value: compact(this.volume24h), hint: "2.67M", tone: "mint" },
      { label: "MIN_HOLDERS", value: String(this.holders), hint: "664", tone: "mint" },
      { label: "MAX_TOP10", value: (0.46 + wobble * 0.02).toFixed(2), hint: "0.45", tone: "amber" },
      { label: "MAX_DEV_BAG", value: (0.058 + wobble * 0.006).toFixed(3), hint: "0.060", tone: "amber" },
      { label: "SOCIAL_MIN", value: (0.69 + wobble * 0.04).toFixed(2), hint: "> 0.55", tone: "pink" },
      { label: "MAX_SLIPPAGE", value: (0.82 + wobble * 0.08).toFixed(2), hint: "1.00", tone: "red" },
    ];
  }

  private buildAgents(): AgentCardData[] {
    const seq = this.seq;
    const priceSpark = this.priceSeries.length > 2 ? this.priceSeries : [DOPE_START * 0.98, DOPE_START, DOPE_START * 1.01];
    const equitySpark = this.equitySeries.length > 2 ? this.equitySeries : [this.balance * 0.99, this.balance];
    const candleSpark = this.candles.length > 2 ? this.candles : [];
    const chiefConfidence = clamp(0.53 + 0.18 * (0.5 + 0.5 * Math.sin(seq * 0.33)), 0, 1);
    const vetScore = clamp(0.2 + 0.46 * (0.5 + 0.5 * Math.cos(seq * 0.27)), 0, 1);
    const socialScore = clamp(0.34 + 0.42 * (0.5 + 0.5 * Math.sin(seq * 0.41 + 1)), 0, 1);
    const riskUsage = clamp(0.32 + 0.25 * (0.5 + 0.5 * Math.sin(seq * 0.23 + 2)), 0, 1);
    const scanProgress = clamp(0.38 + 0.55 * (0.5 + 0.5 * Math.sin(seq * 0.58)), 0, 1);
    const pick = PICKS[Math.floor(seq / 9) % PICKS.length];
    const position = 3_510 + Math.round(Math.sin(seq * 0.3) * 240);
    const badge = (agent: AgentId): string => (this.activeAgent === agent ? "working" : "thinking");
    const confidenceDelta = Math.sin(seq * 0.47) * 0.04;

    return [
      {
        id: "chief",
        name: AGENT_META.chief.name,
        tag: AGENT_META.chief.tag,
        icon: AGENT_META.chief.icon,
        accent: AGENT_META.chief.accent,
        headline: `last pick ${pick}`,
        value: chiefConfidence.toFixed(2),
        sub: `conf ${signed(confidenceDelta, 2)} / leg 2.1k`,
        progress: chiefConfidence,
        status: badge("chief"),
        tone: "pink",
        spark: equitySpark.slice(-20),
        active: this.activeAgent === "chief",
      },
      {
        id: "scan",
        name: AGENT_META.scan.name,
        tag: AGENT_META.scan.tag,
        icon: AGENT_META.scan.icon,
        accent: AGENT_META.scan.accent,
        headline: "finding next moves",
        value: socialScore.toFixed(2),
        sub: `pools ${248 + (seq % 31)} / ${Math.round(this.scanned)} scanned`,
        progress: scanProgress,
        status: badge("scan"),
        tone: "mint",
        spark: priceSpark.slice(-20),
        active: this.activeAgent === "scan",
      },
      {
        id: "vet",
        name: AGENT_META.vet.name,
        tag: AGENT_META.vet.tag,
        icon: AGENT_META.vet.icon,
        accent: AGENT_META.vet.accent,
        headline: "scan / trade / risk eval",
        value: vetScore.toFixed(2),
        sub: vetScore > 0.32 ? "tier 2 / clean" : "tier 3 / caution",
        progress: vetScore,
        status: badge("vet"),
        tone: vetScore > 0.32 ? "cyan" : "red",
        spark: candleSpark.map((c) => c.close),
        active: this.activeAgent === "vet",
      },
      {
        id: "social",
        name: AGENT_META.social.name,
        tag: AGENT_META.social.tag,
        icon: AGENT_META.social.icon,
        accent: AGENT_META.social.accent,
        headline: "the timeline is loud",
        value: socialScore.toFixed(2),
        sub: `mentions ${41 + (seq % 17)} / 5m`,
        progress: socialScore,
        status: badge("social"),
        tone: "red",
        spark: wave(seq, 20, 0.42, 0.46),
        active: this.activeAgent === "social",
      },
      {
        id: "size",
        name: AGENT_META.size.name,
        tag: AGENT_META.size.tag,
        icon: AGENT_META.size.icon,
        accent: AGENT_META.size.accent,
        headline: `target ${fmtUsd(position)}`,
        value: fmtUsd(position),
        sub: "4% of book / 1 leg",
        progress: clamp(position / 9000, 0, 1),
        status: badge("size"),
        tone: "pink",
        spark: equitySpark.slice(-20),
        active: this.activeAgent === "size",
      },
      {
        id: "fills",
        name: AGENT_META.fills.name,
        tag: AGENT_META.fills.tag,
        icon: AGENT_META.fills.icon,
        accent: AGENT_META.fills.accent,
        headline: `out: ${compact(this.volume24h)}`,
        value: `+${this.fills.toLocaleString("en-US")}`,
        sub: `router ${this.latency}ms / 99.2%`,
        progress: 0.78,
        status: badge("fills"),
        tone: "mint",
        spark: this.candles.map((c) => c.volume).slice(-20),
        active: this.activeAgent === "fills",
      },
      {
        id: "risk",
        name: AGENT_META.risk.name,
        tag: AGENT_META.risk.tag,
        icon: AGENT_META.risk.icon,
        accent: AGENT_META.risk.accent,
        headline: "max loss 4% of book",
        value: "4% 1L",
        sub: `usage ${(riskUsage * 100).toFixed(0)}% / drawdown -0.6%`,
        progress: riskUsage,
        status: badge("risk"),
        tone: "amber",
        spark: wave(seq, 20, 0.55, 0.4),
        active: this.activeAgent === "risk",
      },
      {
        id: "crawler",
        name: AGENT_META.crawler.name,
        tag: AGENT_META.crawler.tag,
        icon: AGENT_META.crawler.icon,
        accent: AGENT_META.crawler.accent,
        headline: "holders scraped",
        value: `${(this.holders / 1000).toFixed(3)}k`,
        sub: `12/12 pages / ${1_200 + (seq % 700)} links`,
        progress: 0.84,
        status: badge("crawler"),
        tone: "amber",
        spark: wave(seq + 4, 20, 0.5, 0.32),
        active: this.activeAgent === "crawler",
      },
    ];
  }

  private buildSnapshot(): DashboardSnapshot {
    const pnl = this.balance - this.startBalance;
    const changePct = ((this.price - this.startPrice) / this.startPrice) * 100;
    return {
      seq: this.seq,
      tickMs: this.tickMs,
      day: 11,
      sessionTime: this.timeFor(0),
      symbol: "DOPE",
      price: this.price,
      changePct,
      priceSeries: [...this.priceSeries],
      candles: [...this.candles],
      balance: this.balance,
      balanceSeries: [...this.equitySeries],
      pnl,
      pnlPct: (pnl / this.startBalance) * 100,
      peakBalance: this.peakBalance,
      holders: this.holders,
      scanned: this.scanned,
      volume24h: this.volume24h,
      activeAgent: this.activeAgent,
      agents: this.buildAgents(),
      activity: [...this.activity],
      thresholds: this.thresholds,
      book: { ...this.book, depth: [...this.book.depth] },
      latency: this.latency,
      gas: this.gas,
      fills: this.fills,
      runwayPct: 75.2,
    };
  }
}

export function createMarketEngine(options: EngineOptions = {}): MarketEngine {
  return new MarketEngine(options);
}
